phase3.solution:
heroes = ["Aragorn", "Legolas", "Gimli", "Gandalf"]
ages = [87, 2931, 139, 2019]

hero_ages = {hero: age for hero, age in zip(heroes, ages)}
print(f"Hero ages: {hero_ages}")

old_heroes = {hero: age for hero, age in hero_ages.items() if age > 100}
print(f"Old heroes: {old_heroes}")

uppercase = {hero.upper(): age for hero, age in hero_ages.items()}
print(f"Uppercase: {uppercase}")

labels = {hero: 'immortal' if age > 1000 else 'mortal' for hero, age in hero_ages.items()}
print(f"Labels: {labels}")
